function onLoad() {   //MSSTRUSTES-83
   g_form.setSectionDisplay('comments', false);

   // here as g_user object not working in UI POlicies
   var assigned = g_form.getValue('assigned_to');
   var curr = g_user.userID;

   if(assigned === curr)
   {
	g_form.setMandatory('fcrr_effective_date_er_risk', true);
	g_form.setMandatory('fcrr_result_er_risk',true);
   }
}
